& { overflow: hidden; clip-path: none; }
& .scorebug { background: #071216; font-family: Segoe UI, Arial, sans-serif; }
& .scorebug-team { gap: 2%; padding: 0 2.5%; background: transparent; }
& .scorebug-team-blue { background: linear-gradient(90deg, #21383b, #071216 70%); border-left: 2px solid #97c7c4; }
& .scorebug-team-red { background: linear-gradient(270deg, #21383b, #071216 70%); border-right: 2px solid #d3a4a4; }
& .team-logo { visibility: hidden; flex-basis: 13%; width: 13%; }
& .team-lockup { flex: 1 1 19%; min-width: 0; }
& .team-code { color: #f4f5ef; font-family: Segoe UI, Arial, sans-serif; font-size: clamp(12px, 3.25cqw, 29px);  }
& .team-seed { color: #b7c9c6; font-size: clamp(6px, 1.1cqw, 10px); }
& .team-gold { color: #f4f5ef; font-family: Segoe UI, Arial, sans-serif; font-size: clamp(10px, 2.65cqw, 25px); }
& .team-objective { color: #97c7c4; font-size: clamp(7px, 1.8cqw, 17px); }
& .scorebug-team-red .team-objective { color: #d3a4a4; }
& .scorebug-center { display: grid; grid-template-columns: 1fr 1fr; grid-template-rows: minmax(0, 1fr) 29%; gap: 0; padding: 0; place-items: center; background: linear-gradient(180deg, #14242a 0 70%, #071216 70%); box-shadow: 1px 0 0 #b6ccc8 inset, -1px 0 0 #b6ccc8 inset; }
& .team-kills { min-width: 0; color: #f4f5ef; font-family: Segoe UI, Arial, sans-serif; font-size: clamp(23px, 4.4cqw, 48px); line-height: 1; transform: translateY(3px); }
& .scorebug-center .team-kills:first-child { grid-column: 1; grid-row: 1; }
& .scorebug-center .team-kills:nth-child(3) { grid-column: 2; grid-row: 1; }
& .score-divider { display: none; }
& .game-clock { position: static; grid-column: 1 / -1; grid-row: 2; width: 100%; height: 100%; min-width: 0; display: grid; place-items: center; padding: 0; transform: none; border: 0; background: transparent; color: #f4f5ef; font-family: Segoe UI, Arial, sans-serif; font-size: clamp(12px, 2.3cqw, 22px); line-height: 1; }
& .objective-row { gap: 6%; padding: 0 5%; background: #071216; color: #b7c9c6; font-size: clamp(7px, 1.3cqw, 12px); opacity: 1; border-top: 1px solid #b6ccc8; }
& .team-code, & .team-gold, & .team-kills, & .game-clock { font-weight: 700; } & .objective-row { font-weight: 700; }

